271|    private func labelSplitViewContainers(in view: NSView) {
272|        let windowRect = view.convert(view.bounds, to: nil)
273|        let contentBounds = view.window?.contentView?.bounds ?? .zero
274|        let existingLabel: String? = view.accessibilityLabel()
275|        let role: NSAccessibility.Role? = view.accessibilityRole()
276|        if role == .group,
277|           existingLabel?.isEmpty != false,
278|           windowRect.height >= contentBounds.height * 0.75 {
279|            let semanticLabel: String?
280|            if windowRect.minX <= 20, windowRect.width <= 320 {
281|                semanticLabel = "归档目录"
282|            } else if windowRect.maxX >= contentBounds.width - 20, windowRect.width <= 420 {
283|                semanticLabel = "归档信息"
284|            } else if windowRect.width >= 400 {
285|                semanticLabel = "归档内容"
286|            } else {
287|                semanticLabel = nil
288|            }
289|            if let semanticLabel {
290|                view.setAccessibilityLabel(semanticLabel)
291|                view.setAccessibilityIdentifier("\(semanticLabel)容器")
292|            }
293|        }
294|        if let splitView = view as? NSSplitView {
295|            splitView.setAccessibilityLabel("归档分栏")
296|            for (index, pane) in splitView.arrangedSubviews.enumerated() {
297|                let paneLabel: String
298|                if pane.frame.width <= 320, index == 0 {
299|                    paneLabel = "归档目录"
300|                } else if pane.frame.width <= 400, index == splitView.arrangedSubviews.count - 1 {
301|                    paneLabel = "归档信息"
302|                } else {
303|                    paneLabel = "归档内容"
304|                }
305|                pane.setAccessibilityLabel(paneLabel)
306|                pane.setAccessibilityIdentifier("\(paneLabel)容器")
307|            }
308|        }
309|        for subview in view.subviews {
310|            labelSplitViewContainers(in: subview)
311|        }
312|    }
